void PointcloudBasedOccupancyGridMapNode::obstaclePointcloudCallback(
  const PointCloud2::ConstSharedPtr & input_obstacle_msg)
{
  obstacle_pointcloud_.fromROSMsgAsync(input_obstacle_msg);

  if (obstacle_pointcloud_.header.stamp == raw_pointcloud_.header.stamp) {
    onPointcloudWithObstacleAndRaw();
  }
}

void PointcloudBasedOccupancyGridMapNode::onPointcloudWithObstacleAndRaw()
{
  std::unique_ptr<ScopedTimeTrack> st_ptr;
  if (time_keeper_) st_ptr = std::make_unique<ScopedTimeTrack>(__func__, *time_keeper_);

  if (stop_watch_ptr_) {
    stop_watch_ptr_->toc("processing_time", true);
  }

  // if scan_origin_frame_ is "", replace it with raw_pointcloud_.header.frame_id
  if (scan_origin_frame_.empty()) {
    scan_origin_frame_ = raw_pointcloud_.header.frame_id;
  }

  // Prepare for applying height filter
  if (use_height_filter_) {
    // Make sure that the frame is base_link
    if (raw_pointcloud_.header.frame_id != base_link_frame_) {
      if (!utils::transformPointcloudAsync(
            raw_pointcloud_, *tf2_, base_link_frame_, device_rotation_, device_translation_)) {
        return;
      }
    }
    if (obstacle_pointcloud_.header.frame_id != base_link_frame_) {
      if (!utils::transformPointcloudAsync(
            obstacle_pointcloud_, *tf2_, base_link_frame_, device_rotation_, device_translation_)) {
        return;
      }
    }
    occupancy_grid_map_ptr_->setHeightLimit(min_height_, max_height_);
  } else {
    occupancy_grid_map_ptr_->setHeightLimit(
      -std::numeric_limits<double>::infinity(), std::numeric_limits<double>::infinity());
  }

  // Get from map to sensor frame pose
  Pose robot_pose{};
  Pose gridmap_origin{};
  Pose scan_origin{};
  try {
    robot_pose = utils::getPose(raw_pointcloud_.header.stamp, *tf2_, base_link_frame_, map_frame_);
    gridmap_origin =
      utils::getPose(raw_pointcloud_.header.stamp, *tf2_, gridmap_origin_frame_, map_frame_);
    scan_origin =
      utils::getPose(raw_pointcloud_.header.stamp, *tf2_, scan_origin_frame_, map_frame_);
  } catch (tf2::TransformException & ex) {
    RCLCPP_WARN_STREAM(get_logger(), ex.what());
    return;
  }

  {  // create occupancy grid map and publish it
    std::unique_ptr<ScopedTimeTrack> inner_st_ptr;
    if (time_keeper_)
      inner_st_ptr = std::make_unique<ScopedTimeTrack>("create_occupancy_grid_map", *time_keeper_);

    // Create single frame occupancy grid map
    occupancy_grid_map_ptr_->resetMaps();
    occupancy_grid_map_ptr_->updateOrigin(
      gridmap_origin.position.x - occupancy_grid_map_ptr_->getSizeInMetersX() / 2,
      gridmap_origin.position.y - occupancy_grid_map_ptr_->getSizeInMetersY() / 2);
    occupancy_grid_map_ptr_->updateWithPointCloud(
      raw_pointcloud_, obstacle_pointcloud_, robot_pose, scan_origin);
  }

  if (enable_single_frame_mode_) {
    std::unique_ptr<ScopedTimeTrack> inner_st_ptr;
    if (time_keeper_)
      inner_st_ptr = std::make_unique<ScopedTimeTrack>("publish_occupancy_grid_map", *time_keeper_);

    occupancy_grid_map_ptr_->copyDeviceCostmapToHost();

    // publish
    occupancy_grid_map_pub_->publish(OccupancyGridMapToMsgPtr(
      map_frame_, raw_pointcloud_.header.stamp, robot_pose.position.z,
      *occupancy_grid_map_ptr_));  // (todo) robot_pose may be altered with gridmap_origin
  } else {
    std::unique_ptr<ScopedTimeTrack> inner_st_ptr;
    if (time_keeper_)
      inner_st_ptr =
        std::make_unique<ScopedTimeTrack>("update_and_publish_occupancy_grid_map", *time_keeper_);

    // Update with bayes filter
    occupancy_grid_map_updater_ptr_->update(*occupancy_grid_map_ptr_);
    occupancy_grid_map_updater_ptr_->copyDeviceCostmapToHost();

    // publish
    occupancy_grid_map_pub_->publish(OccupancyGridMapToMsgPtr(
      map_frame_, raw_pointcloud_.header.stamp, robot_pose.position.z,
      *occupancy_grid_map_updater_ptr_));
  }

  if (debug_publisher_ptr_ && stop_watch_ptr_) {
    const double cyclic_time_ms = stop_watch_ptr_->toc("cyclic_time", true);
    const double processing_time_ms = stop_watch_ptr_->toc("processing_time", true);
    const double pipeline_latency_ms =
      std::chrono::duration<double, std::milli>(
        std::chrono::nanoseconds(
          (this->get_clock()->now() - raw_pointcloud_.header.stamp).nanoseconds()))
        .count();
    debug_publisher_ptr_->publish<autoware_internal_debug_msgs::msg::Float64Stamped>(
      "debug/cyclic_time_ms", cyclic_time_ms);
    debug_publisher_ptr_->publish<autoware_internal_debug_msgs::msg::Float64Stamped>(
      "debug/processing_time_ms", processing_time_ms);
    debug_publisher_ptr_->publish<autoware_internal_debug_msgs::msg::Float64Stamped>(
      "debug/pipeline_latency_ms", pipeline_latency_ms);

    checkProcessingTime(processing_time_ms);
  }
}

bool transformPointcloudAsync(
  CudaPointCloud2 & input, const tf2_ros::Buffer & tf2, const std::string & target_frame,
  autoware::cuda_utils::CudaUniquePtr<Eigen::Matrix3f> & device_rotation,
  autoware::cuda_utils::CudaUniquePtr<Eigen::Vector3f> & device_translation)
{
  geometry_msgs::msg::TransformStamped tf_stamped;
  // lookup transform
  try {
    tf_stamped = tf2.lookupTransform(
      target_frame, input.header.frame_id, input.header.stamp, rclcpp::Duration::from_seconds(0.5));
  } catch (tf2::TransformException & ex) {
    RCLCPP_WARN(
      rclcpp::get_logger("probabilistic_occupancy_grid_map"), "Failed to lookup transform: %s",
      ex.what());
    return false;
  }
  // transform pointcloud
  Eigen::Matrix4f tf_matrix = tf2::transformToEigen(tf_stamped.transform).matrix().cast<float>();
  Eigen::Matrix3f rotation = tf_matrix.block<3, 3>(0, 0);
  Eigen::Vector3f translation = tf_matrix.block<3, 1>(0, 3);

  CHECK_CUDA_ERROR(cudaMemcpyAsync(
    device_rotation.get(), rotation.data(), sizeof(Eigen::Matrix3f), cudaMemcpyHostToDevice,
    input.stream));
  CHECK_CUDA_ERROR(cudaMemcpyAsync(
    device_translation.get(), translation.data(), sizeof(Eigen::Vector3f), cudaMemcpyHostToDevice,
    input.stream));

  transformPointCloudLaunch(
    input.data.get(), input.width * input.height, input.point_step, device_rotation.get(),
    device_translation.get(), input.stream);

  input.header.frame_id = target_frame;
  return true;
}

void transformPointCloudLaunch(
  std::uint8_t * points, std::size_t num_points, std::size_t points_step,
  const Eigen::Matrix3f * rotation, const Eigen::Vector3f * translation, cudaStream_t stream)
{
  // Launch kernel
  const int threads_per_block = 256;
  int num_blocks = (num_points + threads_per_block - 1) / threads_per_block;
  transformPointCloudKernel<<<num_blocks, threads_per_block, 0, stream>>>(
    points, num_points, points_step, rotation, translation);
}

__global__ void transformPointCloudKernel(
  std::uint8_t * points, std::size_t num_points, std::size_t points_step,
  const Eigen::Matrix3f * rotation, const Eigen::Vector3f * translation)
{
  int idx = blockIdx.x * blockDim.x + threadIdx.x;
  if (idx >= num_points) {
    return;
  }

  Eigen::Map<Eigen::Vector3f> point_map(reinterpret_cast<float *>(points + idx * points_step));
  point_map = rotation[0] * point_map + translation[0];
}

geometry_msgs::msg::Pose getPose(
  const builtin_interfaces::msg::Time & stamp, const tf2_ros::Buffer & tf2,
  const std::string & source_frame, const std::string & target_frame)
{
  geometry_msgs::msg::Pose pose;
  geometry_msgs::msg::TransformStamped tf_stamped;
  tf_stamped =
    tf2.lookupTransform(target_frame, source_frame, stamp, rclcpp::Duration::from_seconds(0.5));
  pose = autoware_utils::transform2pose(tf_stamped.transform);
  return pose;
}

void OccupancyGridMapInterface::updateOrigin(double new_origin_x, double new_origin_y) {
  // project the new origin into the grid
  int cell_ox{static_cast<int>(std::floor((new_origin_x - origin_x_) / resolution_))};
  int cell_oy{static_cast<int>(std::floor((new_origin_y - origin_y_) / resolution_))};

  // compute the associated world coordinates for the origin cell
  // because we want to keep things grid-aligned
  double new_grid_ox{origin_x_ + cell_ox * resolution_};
  double new_grid_oy{origin_y_ + cell_oy * resolution_};

  // To save casting from unsigned int to int a bunch of times
  int size_x{static_cast<int>(size_x_)};
  int size_y{static_cast<int>(size_y_)};

  // we need to compute the overlap of the new and existing windows
  int lower_left_x{std::min(std::max(cell_ox, 0), size_x)};
  int lower_left_y{std::min(std::max(cell_oy, 0), size_y)};
  int upper_right_x{std::min(std::max(cell_ox + size_x, 0), size_x)};
  int upper_right_y{std::min(std::max(cell_oy + size_y, 0), size_y)};

  unsigned int cell_size_x = upper_right_x - lower_left_x;
  unsigned int cell_size_y = upper_right_y - lower_left_y;

  // we need a map to store the obstacles in the window temporarily
  std::vector<unsigned char> local_map;

// #ifdef USE_CUDA
  using autoware::occupancy_grid_map::utils::copyMapRegionLaunch;
  if (use_cuda_) {
    copyMapRegionLaunch(
      device_costmap_.get(), lower_left_x, lower_left_y, size_x_, size_y_,
      device_costmap_aux_.get(), 0, 0, cell_size_x, cell_size_y, cell_size_x, cell_size_y, stream_);

    cudaMemsetAsync(
      device_costmap_.get(), cost_value::NO_INFORMATION, size_x_ * size_y_ * sizeof(std::uint8_t),
      stream_);
// #else
//   if (use_cuda_) 
//     RCLCPP_ERROR(
//       rclcpp::get_logger("pointcloud_based_occupancy_grid_map"),
//       "The code was compiled without cuda.");
//     return;
// #endif
  } else {
    local_map.resize(static_cast<size_t>(cell_size_x) * static_cast<size_t>(cell_size_y));

    // copy the local window in the costmap to the local map
    copyMapRegion(
      costmap_, lower_left_x, lower_left_y, size_x_, local_map.data(), 0, 0, cell_size_x,
      cell_size_x, cell_size_y);

    // now we'll set the costmap to be completely unknown if we track unknown space
    nav2_costmap_2d::Costmap2D::resetMaps();
  }

  // update the origin with the appropriate world coordinates
  origin_x_ = new_grid_ox;
  origin_y_ = new_grid_oy;

  // compute the starting cell location for copying data back in
  int start_x{lower_left_x - cell_ox};
  int start_y{lower_left_y - cell_oy};

  if (first_iteration_) {
    origin_x_ = new_grid_ox;
    origin_y_ = new_grid_oy;
    first_iteration_ = false;
    return;
  }

  // now we want to copy the overlapping information back into the map, but in its new location
// #ifdef USE_CUDA
  if (use_cuda_) {
    if (
      start_x < 0 || start_y < 0 || start_x + cell_size_x > size_x_ ||
      start_y + cell_size_y > size_y_) {
      RCLCPP_ERROR(
        rclcpp::get_logger("pointcloud_based_occupancy_grid_map"),
        "update coordinates are negative or out of bounds: start.x=%d, start.y=%d, cell_size.x=%d, "
        "cell_size.y=%d size_x:%d, size_y=%d",
        start_x, start_y, cell_size_x, cell_size_y, size_x_, size_y_);
      return;
    }

    copyMapRegionLaunch(
      device_costmap_aux_.get(), 0, 0, cell_size_x, cell_size_y, device_costmap_.get(), start_x,
      start_y, size_x_, size_y_, cell_size_x, cell_size_y, stream_);
// #else
//   if (use_cuda_) 
//     RCLCPP_ERROR(
//       rclcpp::get_logger("pointcloud_based_occupancy_grid_map"),
//       "The code was compiled without cuda.");
//     return;
// #endif
  } else {
    copyMapRegion(
      local_map.data(), 0, 0, cell_size_x, costmap_, start_x, start_y, size_x_, cell_size_x,
      cell_size_y);
  }
}

void copyMapRegionLaunch(
  const std::uint8_t * source_map, unsigned int sm_lower_left_x, unsigned int sm_lower_left_y,
  unsigned int sm_size_x, unsigned int sm_size_y, std::uint8_t * dest_map,
  unsigned int dm_lower_left_x, unsigned int dm_lower_left_y, unsigned int dm_size_x,
  unsigned int dm_size_y, unsigned int region_size_x, unsigned int region_size_y,
  cudaStream_t stream)
{
  const int threads_per_block = 256;
  const int num_blocks =
    (region_size_x * region_size_y + threads_per_block - 1) / threads_per_block;

  if (num_blocks == 0) {
    return;
  }

  copyMapRegionKernel<<<num_blocks, threads_per_block, 0, stream>>>(
    source_map, sm_lower_left_x, sm_lower_left_y, sm_size_x, sm_size_y, dest_map, dm_lower_left_x,
    dm_lower_left_y, dm_size_x, dm_size_y, region_size_x, region_size_y);
}

__global__ void copyMapRegionKernel(
  const std::uint8_t * source_map, unsigned int sm_lower_left_x, unsigned int sm_lower_left_y,
  unsigned int sm_size_x, unsigned int sm_size_y, std::uint8_t * dest_map,
  unsigned int dm_lower_left_x, unsigned int dm_lower_left_y, unsigned int dm_size_x,
  unsigned int dm_size_y, unsigned int region_size_x, unsigned int region_size_y)
{
  const int idx = blockIdx.x * blockDim.x + threadIdx.x;
  if (idx >= region_size_x * region_size_y) return;

  const int region_y = idx / region_size_x;
  const int region_x = idx % region_size_x;

  const int sm_index =
    sm_lower_left_y * sm_size_x + sm_lower_left_x + region_y * sm_size_x + region_x;
  const int dm_index =
    dm_lower_left_y * dm_size_x + dm_lower_left_x + region_y * dm_size_x + region_x;

  if (sm_index < sm_size_x * sm_size_y && dm_index < dm_size_x * dm_size_y) {
    dest_map[dm_index] = source_map[sm_index];
  }
}

void copyMapRegion(
  data_type * source_map, unsigned int sm_lower_left_x,
  unsigned int sm_lower_left_y,
  unsigned int sm_size_x, data_type * dest_map, unsigned int dm_lower_left_x,
  unsigned int dm_lower_left_y, unsigned int dm_size_x, unsigned int region_size_x,
  unsigned int region_size_y)
{
  // we'll first need to compute the starting points for each map
  data_type * sm_index = source_map + (sm_lower_left_y * sm_size_x + sm_lower_left_x);
  data_type * dm_index = dest_map + (dm_lower_left_y * dm_size_x + dm_lower_left_x);

  // now, we'll copy the source map into the destination map
  for (unsigned int i = 0; i < region_size_y; ++i) {
    memcpy(dm_index, sm_index, region_size_x * sizeof(data_type));
    sm_index += sm_size_x;
    dm_index += dm_size_x;
  }
}

bool OccupancyGridMapBBFUpdater::update(
  const OccupancyGridMapInterface & single_frame_occupancy_grid_map)
{
  updateOrigin(
    single_frame_occupancy_grid_map.getOriginX(), single_frame_occupancy_grid_map.getOriginY());

  if (use_cuda_ != single_frame_occupancy_grid_map.isCudaEnabled()) {
    throw std::runtime_error("The CUDA setting of the updater and the map do not match.");
  }

// #ifdef USE_CUDA
  if (use_cuda_) {
    applyBBFLaunch(
      single_frame_occupancy_grid_map.getDeviceCostmap().get(), device_probability_matrix_.get(),
      Index::NUM_STATES, Index::FREE, Index::OCCUPIED, cost_value::FREE_SPACE,
      cost_value::LETHAL_OBSTACLE, cost_value::NO_INFORMATION, v_ratio_,
      getSizeInCellsX() * getSizeInCellsY(), device_costmap_.get(), stream_);
// #else
//   if (use_cuda_) {
//     RCLCPP_ERROR(
//       rclcpp::get_logger("pointcloud_based_occupancy_grid_map"),
//       "The code was compiled without cuda.");
//     return false;
// #endif
  } else {
    for (unsigned int x = 0; x < getSizeInCellsX(); x++) {
      for (unsigned int y = 0; y < getSizeInCellsY(); y++) {
        unsigned int index = getIndex(x, y);
        costmap_[index] = applyBBF(single_frame_occupancy_grid_map.getCost(x, y), costmap_[index]);
      }
    }
  }

  return true;
}

